      { q: "How did Tenochtitlan's population compare to major European cities of the same era?", choices: ["It was much smaller than any European city", "It was likely larger than London or Paris at the time", "There is no way to compare them", "It had exactly the same population as Rome"], answer: 1, explain: "Tenochtitlan's estimated population exceeded that of London or Paris at the time." },
      { q: "What were chinampas, and why were they important?", choices: ["A type of Aztec weapon", "A style of clothing", "A religious ceremony", "Artificial floating gardens that expanded farmland to feed the growing city"], answer: 3, explain: "Chinampas were artificial farmland that helped feed Tenochtitlan's large population." },
      { q: "How did the Aztec Empire's political structure actually function?", choices: ["It was ruled directly by Spain from the start", "As one single, perfectly unified nation-state", "It had no political structure at all", "As a network of city-states bound together through conquest and tribute"], answer: 3, explain: "The empire functioned as a network of city-states connected by conquest and tribute." },
      { q: "What connection does modern Mexico City have to Tenochtitlan?", choices: ["There is no connection between them", "Mexico City is 1,000 miles away from the site", "Mexico City was built directly on top of Tenochtitlan's ruins", "They are in two completely different countries"], answer: 2, explain: "Mexico City was built on the ruins of Tenochtitlan after the Spanish conquest." }
